def find_max(words):
    max_unique_count = 0
    result = ""

    for word in words:
        unique_chars = set(word)
        unique_count = len(unique_chars)

        if (unique_count > max_unique_count) or (unique_count == max_unique_count and word < result):
            max_unique_count = unique_count
            result = word

    return result

